using System.Text;
using MimeKit;
using Msg2Eml.Core;

namespace Msg2Eml.Tests;

/// <summary>
/// One test per risk case of the plan (section 4), on synthetic fixtures generated by
/// <c>tools/gen-fixtures</c> with MsgKit. Every expectation below is known because the
/// fixture was built from that very data.
/// </summary>
public class SyntheticFixtureTests
{
    private readonly MsgConverter _converter = new();

    private (MimeMessage Mime, ConversionStats Stats, byte[] Eml) Convert(string fixture)
    {
        using var fs = Fixtures.OpenSynthetic(fixture);
        var result = _converter.Convert(fs);
        var mime = MimeMessage.Load(new MemoryStream(result.Eml));
        Assert.Empty(EmlFidelity.Validate(mime));
        return (mime, result.Stats, result.Eml);
    }

    [Theory]
    [InlineData("plain-text.msg")]
    [InlineData("native-html.msg")]
    [InlineData("inline-images.msg")]
    [InlineData("attachments.msg")]
    [InlineData("unicode.msg")]
    [InlineData("ex-recipient.msg")]
    [InlineData("rtf-encapsulated-html.msg")]
    [InlineData("rtf-only.msg")]
    [InlineData("msg-as-attachment.msg")]
    [InlineData("health.msg")]
    public void EveryMailFixture_ProducesWellFormedEml(string fixture)
    {
        var (mime, _, eml) = Convert(fixture);

        Assert.Single(mime.Headers, h => h.Id == HeaderId.From);
        Assert.Single(mime.Headers, h => h.Id == HeaderId.Date);
        Assert.Single(mime.Headers, h => h.Id == HeaderId.MessageId);
        Assert.NotEmpty(mime.From);
        Assert.Equal(new DateTimeOffset(2026, 3, 15, 10, 30, 0, TimeSpan.Zero), mime.Date);

        // Only CRLF line endings, no bare 8-bit bytes anywhere (everything is encoded).
        for (var i = 0; i < eml.Length; i++)
        {
            if (eml[i] == (byte)'\n') Assert.True(i > 0 && eml[i - 1] == (byte)'\r', $"bare LF at {i}");
            if (eml[i] == (byte)'\r') Assert.True(i + 1 < eml.Length && eml[i + 1] == (byte)'\n', $"bare CR at {i}");
            Assert.True(eml[i] < 0x80, $"8-bit byte at {i}");
        }

        // Every text part declares its encoding explicitly.
        foreach (var part in mime.BodyParts.OfType<TextPart>())
            Assert.NotEqual(ContentEncoding.Default, part.ContentTransferEncoding);
    }

    [Fact]
    public void PlainText_NoTransportHeaders_UsesMapiFallback()
    {
        var (mime, stats, _) = Convert("plain-text.msg");

        Assert.False(stats.HasTransportHeaders);
        Assert.Equal(BodyKind.Text, stats.BodyKind);
        Assert.Equal("Plain text message", mime.Subject);
        Assert.Equal("alice.sender@example.org", mime.From.Mailboxes.Single().Address);
        Assert.Equal("Alice Sender", mime.From.Mailboxes.Single().Name);
        Assert.Equal("bob.recipient@example.net", mime.To.Mailboxes.Single().Address);
        Assert.Equal("carol@example.net", mime.Cc.Mailboxes.Single().Address);
        Assert.Equal("dave@example.net", mime.Bcc.Mailboxes.Single().Address);
        Assert.EndsWith("@msg2eml.generated", mime.MessageId);
        Assert.Null(mime.HtmlBody);
        Assert.Contains("accents: è é à ù and a euro sign €", mime.TextBody);
    }

    [Fact]
    public void NativeHtml_WithTransportHeaders_PreservesThemAndKeepsContentLanguage()
    {
        var (mime, stats, eml) = Convert("native-html.msg");

        Assert.True(stats.HasTransportHeaders);
        Assert.Equal(BodyKind.TextAndHtml, stats.BodyKind);
        Assert.Equal("native-html-0001@example.org", mime.MessageId);
        Assert.Equal("msg2eml", mime.Headers["X-Test-Fixture"]);
        Assert.NotNull(mime.Headers["Received"]);

        // MimeKit routes Content-* headers to the body entity on load, so check the raw top-level block.
        var text = Encoding.ASCII.GetString(eml);
        var topHeaders = text[..text.IndexOf("\r\n\r\n", StringComparison.Ordinal)];
        Assert.Contains("\r\nContent-Language: en-US", topHeaders);
        Assert.Equal(1, text.Split("Content-Language:").Length - 1);
        Assert.Equal("en-US", mime.Body!.Headers[HeaderId.ContentLanguage]);
        Assert.Equal("Native HTML message", mime.Subject);
        Assert.IsType<MultipartAlternative>(mime.Body);
        Assert.Contains("<b>Bob</b>", mime.HtmlBody);
        Assert.Contains("12,50 €", mime.TextBody);
    }

    [Fact]
    public void InlineImages_ReferencedCidsAreInline_UnreferencedBecomesAttachment()
    {
        var (mime, stats, _) = Convert("inline-images.msg");

        Assert.Equal(2, stats.InlineAttachments);
        Assert.Equal(1, stats.Attachments);

        var related = mime.BodyParts.OfType<MimePart>().Where(p => p.ContentDisposition?.Disposition == ContentDisposition.Inline).ToList();
        Assert.Equal(["banner.gif@fixture", "logo.png@fixture"], related.Select(p => p.ContentId).Order());
        Assert.All(related, p => Assert.True(p.ContentType.MediaType == "image"));

        var attachment = mime.Attachments.OfType<MimePart>().Single();
        Assert.Equal("unreferenced.png", attachment.FileName);
        Assert.Equal(ContentDisposition.Attachment, attachment.ContentDisposition!.Disposition);

        // Every cid in the HTML resolves (also enforced by EmlFidelity.Validate in Convert()).
        Assert.Equal(2, EmlFidelity.Cids(mime.HtmlBody!).Count());
    }

    [Fact]
    public void Attachments_KeepBytesNamesAndTypes()
    {
        var (mime, stats, _) = Convert("attachments.msg");

        Assert.Equal(4, stats.Attachments);
        var parts = mime.Attachments.OfType<MimePart>().ToDictionary(p => p.FileName!);

        Assert.Equal("application/pdf", parts["report.pdf"].ContentType.MimeType);
        Assert.StartsWith("%PDF-1.4", Encoding.ASCII.GetString(Decode(parts["report.pdf"])));

        Assert.Equal("text/plain", parts["relazione-è-ü-日本.txt"].ContentType.MimeType);
        Assert.Equal("Testo con àccenti.\r\n", Encoding.UTF8.GetString(Decode(parts["relazione-è-ü-日本.txt"])));

        Assert.Equal("application/octet-stream", parts["README"].ContentType.MimeType);
        Assert.Empty(Decode(parts["empty.bin"]));

        Assert.All(parts.Values, p => Assert.Equal(ContentEncoding.Base64, p.ContentTransferEncoding));
        Assert.All(parts.Values, p => Assert.Equal(ContentDisposition.Attachment, p.ContentDisposition!.Disposition));
    }

    [Fact]
    public void Unicode_SubjectAddressesAndBodies_SurviveRoundTrip()
    {
        var (mime, _, _) = Convert("unicode.msg");

        Assert.Equal("Oggetto con àccenti, € e 日本語 🙂", mime.Subject);
        Assert.Equal("Zoë Sénder", mime.From.Mailboxes.Single().Name);
        Assert.Equal("Björn Ünicode", mime.To.Mailboxes.Single().Name);
        Assert.Equal("Corpo con àccenti, € e 日本語 🙂", mime.TextBody!.Trim());
        Assert.Equal("Corpo con àccenti, € e 日本語 🙂", EmlFidelity.Visible(mime.HtmlBody!));
    }

    [Fact]
    public void ExchangeRecipient_WithoutSmtp_GetsPlaceholderAndKeepsName()
    {
        var (mime, stats, _) = Convert("ex-recipient.msg");

        Assert.Equal(1, stats.UnresolvedRecipients);
        var to = mime.To.Mailboxes.Single();
        Assert.Equal("Bob Exchange", to.Name);
        Assert.Equal("unknown@invalid", to.Address);
        Assert.Equal("carol@example.net", mime.Cc.Mailboxes.Single().Address);
    }

    [Fact]
    public void RtfEncapsulatedHtml_IsDeEncapsulated()
    {
        var (mime, stats, _) = Convert("rtf-encapsulated-html.msg");

        Assert.Equal(BodyKind.TextAndHtml, stats.BodyKind);
        Assert.Contains("<b>RTF-encapsulated</b>", mime.HtmlBody);
        Assert.Equal("Hello from RTF-encapsulated HTML. Accents: è à ù €", EmlFidelity.Visible(mime.HtmlBody!));
        Assert.Contains("Accents: è à ù €", mime.TextBody);
    }

    [Fact]
    public void RtfOnly_KeepsBodyAsRtfAttachment()
    {
        var (mime, stats, _) = Convert("rtf-only.msg");

        Assert.Equal(BodyKind.RtfOnly, stats.BodyKind);
        var rtf = mime.Attachments.OfType<MimePart>().Single();
        Assert.Equal("body.rtf", rtf.FileName);
        Assert.Equal("application/rtf", rtf.ContentType.MimeType);
        Assert.Contains("This body exists only as RTF.", Encoding.UTF8.GetString(Decode(rtf)));
        Assert.Contains("RTF-only message", mime.TextBody);
    }

    [Fact]
    public void MsgAttachedAsFile_StaysAnOutlookAttachment()
    {
        var (mime, stats, _) = Convert("msg-as-attachment.msg");

        Assert.Equal(0, stats.NestedMessages);
        Assert.Equal(1, stats.Attachments);
        var att = mime.Attachments.OfType<MimePart>().Single();
        Assert.Equal("forwarded.msg", att.FileName);
        Assert.Equal("application/vnd.ms-outlook", att.ContentType.MimeType);
        Assert.Equal(Fixtures.OleMagic, Decode(att)[..8]);
    }

    [Theory]
    [InlineData("appointment.msg")]
    [InlineData("task.msg")]
    [InlineData("contact.msg")]
    public void NonMailTypes_AreRejectedAsUnsupported(string fixture)
    {
        using var fs = Fixtures.OpenSynthetic(fixture);
        var ex = Assert.Throws<ConversionException>(() => _converter.Convert(fs));
        Assert.Equal(ConversionErrorCode.UnsupportedMessageType, ex.Code);
    }

    [Theory]
    [InlineData("native-html.msg")]
    [InlineData("attachments.msg")]
    public void TruncatedFixtures_FailWithApplicationError(string fixture)
    {
        var full = File.ReadAllBytes(Fixtures.Synthetic(fixture));
        foreach (var fraction in new[] { 0.1, 0.5, 0.9 })
        {
            var truncated = full[..(int)(full.Length * fraction)];
            var ex = Record.Exception(() => _converter.Convert(new MemoryStream(truncated)));
            Assert.True(ex is null or ConversionException, $"{fixture} at {fraction}: {ex?.GetType().Name}");
        }
    }

    [Fact]
    public void SameInput_ProducesEquivalentOutput()
    {
        // Boundaries are random, so byte equality is not expected: content equality is.
        var a = Convert("inline-images.msg").Mime;
        var b = Convert("inline-images.msg").Mime;
        Assert.Empty(EmlFidelity.Compare(a, b));
    }

    private static byte[] Decode(MimePart part)
    {
        using var ms = new MemoryStream();
        part.Content!.DecodeTo(ms);
        return ms.ToArray();
    }
}
